import{_ as t,o as n,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"🔬 科学日报 | 2026年9月22日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-09-22.md","filePath":"science-log/src/science-daily/2026-09-22.md"}'),s={name:"science-log/src/science-daily/2026-09-22.md"};function a(g,o,i,c,p,u){return n(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="🔬-科学日报-2026年9月22日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年9月22日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年9月22日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年9月22日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第29期（2026-09-22 当日原版简讯，共 10 条） 分析日期：2026-09-22 版本：扩展版（10 条深度 + 交叉关联） 取证：CrossRef 逐条核验（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424），DOI 与作者均实测回填</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-核试验停止多年后-万塔山仍在-复活-断层" tabindex="-1">1. 核试验停止多年后，万塔山仍在&quot;复活&quot;断层 <a class="header-anchor" href="#_1-核试验停止多年后-万塔山仍在-复活-断层" aria-label="Permalink to &quot;1. 核试验停止多年后，万塔山仍在&quot;复活&quot;断层&quot;">​</a></h3><p><strong>原文</strong>：地下核爆炸通常只产生短寿命地震序列，但朝鲜丰溪里万塔山是反例：2017 年最后一次大当量爆炸后地震活动持续多年并增强，从弥散演化为沿断裂控制结构的空间有序分布；17 年连续波形显示浅部断层延迟复活，指向临界应力地壳体积内的渐进应力重分布。</p><p><strong>深度扩展</strong>：</p><p>该研究由 Fan Xingli、Kim Kwang-Hee、Kang Su Young、Liu Lanbo 等完成，2026-09-17 发表于《Science》（DOI: 10.1126/science.adx5917）。团队分析了丰溪里核试验场近 17 年的连续地震波形，把 2017 年 9 月那次大当量（外界估计约 100–200 千吨级）爆炸之后的余震序列做了逐年的空间迁移追踪。</p><p>关键在于两个反直觉的观测：其一，序列<strong>没有衰减</strong>，反而活动率逐年上升；其二，余震不是随机散布，而是逐步&quot;排队&quot;到断裂控制的方向上——这是典型的<strong>流体/应力沿断层迁移</strong>的特征，而非爆炸当场的破碎效应。作者据此提出机制：爆炸在地下制造了一个处于<strong>临界应力状态</strong>的地壳体积，之后应力通过孔隙压扩散与断层弱化缓慢重分布，延迟触发浅部断层的滑动。</p><p>为什么重要：核试验监测长期以&quot;爆炸窗口&quot;（当场释放的地震波）为判据，把余震当作可忽略的尾巴。万塔山提示，在特定地质条件下，一次核试验可以在<strong>数年尺度</strong>上持续改造区域地震危险性——这对《全面禁止核试验条约》的地震核查与周边地区风险评估都是必须新增的变量。</p><p><strong>跨主题关联</strong>：与 <code>topics/earth-science/2026-q3.md</code> 中 2026-09-16 期&quot;日本地震黏土层晚 13 年才响应&quot;同族——地壳的响应时间常数远超人类直觉；本条与 <code>topics/earth-science/science-daily-2026-09-22.md</code> 已沉淀的地球科学专题互补（后者侧重构造含义，本条补齐核监测含义）。</p><hr><h3 id="_2-多细胞器空间图谱-不用转录组也能读出组织里的细胞状态" tabindex="-1">2. 多细胞器空间图谱：不用转录组也能读出组织里的细胞状态 <a class="header-anchor" href="#_2-多细胞器空间图谱-不用转录组也能读出组织里的细胞状态" aria-label="Permalink to &quot;2. 多细胞器空间图谱：不用转录组也能读出组织里的细胞状态&quot;">​</a></h3><p><strong>原文</strong>：作者提出空间细胞器组学（sOrganellomics），用多细胞器特征对细胞状态分类与空间映射；肝脏与胰腺中能区分主要细胞类群，肝细胞在经典分区内形成混居群落，支持更细的&quot;亚分区多样性&quot;模型；营养应激会重塑组织方式，活体成像把禁食诱导的细胞器重塑与线粒体膜电位改变联系起来。</p><p><strong>深度扩展</strong>：</p><p>该工作由 Adhikari Raghabendra、Hillsley Alexander、Johnson Alana Dowdell 等完成，2026-09-17 发表于《Science》（DOI: 10.1126/science.ady6372）。现有单细胞空间组学几乎全部以<strong>转录组</strong>为坐标轴，代价是丢失了细胞器形态这一直接反映代谢与应激状态的变量。</p><p>sOrganellomics 的技术路径是：自动图像分割 + 机器学习分类器，把每个细胞拆成多细胞器特征向量（线粒体网络形态、内质网铺展度、溶酶体丰度与定位等），再用这些特征对细胞状态做无监督聚类与空间映射。在肝脏中，得到的结果比经典&quot;分区（zonation）&quot;模型更细——同处一个经典分区内的肝细胞，其细胞器定义的状态并不一致，而是形成<strong>混居群落</strong>，提示组织存在&quot;亚分区&quot;层级的多样性。</p><p>最有说服力的一环是<strong>扰动实验</strong>：禁食（营养应激）会系统性重塑这套细胞器组织方式，活体成像进一步把禁食诱导的细胞器重塑与线粒体膜电位变化实时对应。这意味着细胞器架构可以作为组织适应的<strong>结构性读数</strong>——一个不依赖测序、可直接从成像读出细胞功能状态的窗口，对病理诊断与在体监测有直接实用价值。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 中代谢/肝病方向互补；其&quot;用结构直接读出功能状态&quot;的思路与 <code>topics/physics/quantum-computing-deep.md</code> 里&quot;用物理量本身作为计算资源&quot;的取向同构——都在减少对中间转录层的依赖。</p><hr><h3 id="_3-中性原子量子比特阵列-每秒-500-次的快速连续重装载" tabindex="-1">3. 中性原子量子比特阵列：每秒 500 次的快速连续重装载 <a class="header-anchor" href="#_3-中性原子量子比特阵列-每秒-500-次的快速连续重装载" aria-label="Permalink to &quot;3. 中性原子量子比特阵列：每秒 500 次的快速连续重装载&quot;">​</a></h3><p><strong>原文</strong>：中性原子处理器中原子丢失是跑深电路的主要障碍，既有补齐方案耗时比门操作长一个数量级以上；本文用亚稳态 ¹⁷¹Yb 量子比特实现快速连续重装载，速率达每秒 500 次，把制备/非破坏成像/初始化算进去仍能以每秒 30 次初始化随机填充阵列，且重装载不扰动已处于亚稳态的量子比特。</p><p><strong>深度扩展</strong>：</p><p>该研究由 Li Yiyi、Bao Yicheng、Peper Michael 等完成，2026-09-17 发表于《Science》（DOI: 10.1126/science.adz9952）。中性原子方案的可扩展性来自&quot;光镊阵列可以排布上千个原子&quot;，但它的致命伤是<strong>原子会掉</strong>：与真空背景碰撞、或成像/门操作中的散射，都会让一个位点变空，而空位会阻断整个电路的执行。</p><p>传统补原子方案是&quot;停下来、重新装载、再启动&quot;，这一段的耗时比一次门操作长一个数量级以上，于是补原子成了深电路的新瓶颈。本文的做法是把补原子变成<strong>后台循环</strong>：在计算区旁维持一个持续装载的原子库，用移动光镊按需把原子&quot;搬&quot;进空位，提取速率最高达 500 次/秒。更关键的是量子比特选在<strong>亚稳态</strong> ¹⁷¹Yb——重装载过程不会破坏已就绪量子比特的相干性，因此计算可以不被中断地继续。</p><p>把单原子制备、非破坏成像与初始化全部计入，随机填充的阵列仍能维持 30 次/秒的初始化吞吐。作者认为这为&quot;深度不受限&quot;的容错量子电路打下基础——把纠错/维护从算法层下沉到硬件循环。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/science-daily-2026-09-22.md</code> 已沉淀的量子物理专题直接对应（该文件以&quot;测量必须非破坏&quot;为串线判据）；亦见 <code>topics/physics/quantum-computing-deep.md</code> 的容错路线讨论。</p><hr><h3 id="_4-异源皮层-把人源类器官长进小鼠大脑-拿到回路与行为层面的读出" tabindex="-1">4. 异源皮层：把人源类器官长进小鼠大脑，拿到回路与行为层面的读出 <a class="header-anchor" href="#_4-异源皮层-把人源类器官长进小鼠大脑-拿到回路与行为层面的读出" aria-label="Permalink to &quot;4. 异源皮层：把人源类器官长进小鼠大脑，拿到回路与行为层面的读出&quot;">​</a></h3><p><strong>原文</strong>：作者用遗传策略清除小鼠新皮层与海马中的谷氨酸能神经元（apallial），在新生期植入人源皮层类器官（hCO），得到&quot;异源皮层&quot;小鼠；hCO 占据大部分皮层体积，生成含第 5 层端脑外投射神经元在内的多种人皮层细胞类型；活体钙成像与电生理显示有序活动，运动大体保留但肢体协调出现选择性差异、自发行为组织改变。</p><p><strong>深度扩展</strong>：</p><p>该工作由 Kaganovsky Konstantin、Kelley Kevin W.、Gschwind Tilo、Harary Paul M. 等完成，2026-09-16 发表于《Nature》（DOI: 10.1038/s41586-026-11032-2）。人脑组织极难获取，用人干细胞来源的类器官（organoid）补位是趋势，但把类器官移植进啮齿动物时，一直受两件事制约：<strong>空间被宿主组织挤占</strong>，以及<strong>宿主神经元与移植组织争夺回路连接</strong>。</p><p>本文的破局点是先&quot;腾地方&quot;：用遗传手段特异清除小鼠新皮层与海马的谷氨酸能神经元（apallial 模型），再把新生期人源皮层类器官（hCO）植入皮层腔。失去占位竞争者后，hCO 得以占据大部分皮层体积，并分化出<strong>多种人皮层细胞类型</strong>，包括第 5 层端脑外投射神经元——这是人皮层输出通路的关键细胞类型，此前很难在移植体中稳定得到。</p><p>整合证据来自活体钙成像与电生理：人神经元与小鼠神经系统建立了功能连接，并显示出类似<strong>发育中回路</strong>的有序自发活动模式（而非随机放电）。行为层面，小鼠的基本运动保留，但肢体协调出现选择性缺陷、自发行为的组织方式改变——说明人源组织确实参与了行为环路的构建，而不是被动&quot;寄居&quot;。该平台还能在&quot;发育中人皮层细胞损伤&quot;模型上做行为读出，为人神经发育与疾病研究提供了一个可操作的体内窗口。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/index.md</code> 的脑类器官/回路方向互补；亦与 <code>topics/neuroscience/science-daily-2026-09-13.md</code> 的神经发育主题呼应。</p><hr><h3 id="_5-保护现存热带森林-比事后恢复更划算" tabindex="-1">5. 保护现存热带森林，比事后恢复更划算 <a class="header-anchor" href="#_5-保护现存热带森林-比事后恢复更划算" aria-label="Permalink to &quot;5. 保护现存热带森林，比事后恢复更划算&quot;">​</a></h3><p><strong>原文</strong>：作者在巴西亚马逊毁林前沿，用深入野外评估加高分辨率遥感，比较三类干预的观测结果与反事实结果，量化生物多样性与碳收益及成本；结果显示避免干扰（保护）收益最大且比恢复更具成本效益，但组合干预总收益最大。</p><p><strong>深度扩展</strong>：</p><p>该研究由 Miranda Leonardo S.、Thomson James R.、Ferreira Joice 等完成，2026-09-17 发表于《Science》（DOI: 10.1126/science.adx9928）。应对生物多样性与气候危机有两大策略——<strong>阻止毁林</strong>（避免森林干扰）与<strong>推动恢复</strong>（reforestation/restoration）——但长期以来&quot;避免干扰&quot;在政策与资金中关注度低得多，且三类干预（保护、恢复、组合）的相对成本效益从未被放在同一把尺子上量化。</p><p>方法上，团队在巴西亚马逊毁林前沿布点，把<strong>深入野外生物多样性调查</strong>（物种层面）与<strong>高分辨率遥感</strong>（碳储量与景观结构）结合，并构造<strong>反事实</strong>（如果没有该干预，这块地会怎样）来估计净收益，再把收益除以成本得到成本效益比。</p><p>结论清晰且稳健：在多种收益与成本假设下，<strong>避免干扰（保护）</strong> 都同时给出最大的生物多样性与碳收益，并且<strong>单位成本收益高于恢复</strong>——保护一块现有森林远比砍掉再种回来便宜。但也有一个不能省略的补充：把三者<strong>组合</strong>起来时总收益最大，对扭转生物多样性和碳损失不可或缺。换言之，&quot;保护优先，但保护不能单独完成任务&quot;——这正是政策上最容易被误读为二选一的地方。</p><p><strong>跨主题关联</strong>：与 <code>topics/earth-science/index.md</code> 的生态/碳循环方向互补；其&quot;先保住存量、再谈增量&quot;的优先级逻辑与 <code>topics/investment-methods/</code> 中&quot;控制回撤优先于追逐收益&quot;的风险管理取向同构。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-radar-腹部-ct-的专家级通用视觉语言模型" tabindex="-1">6. RADAR：腹部 CT 的专家级通用视觉语言模型 <a class="header-anchor" href="#_6-radar-腹部-ct-的专家级通用视觉语言模型" aria-label="Permalink to &quot;6. RADAR：腹部 CT 的专家级通用视觉语言模型&quot;">​</a></h3><p><strong>原文</strong>：作者开发 RADAR，在 40 万余例增强腹部 CT、1500 万&quot;按解剖结构组织&quot;的图像-文本对上训练，直接从临床报告学习、无需人工标注；在 18 个解剖结构、146 种影像征象上达到高诊断性能且泛化稳健，读片研究中辅助 26 名放射科医生平均提升诊断灵敏度约 10%。</p><p><strong>深度扩展</strong>：</p><p>该工作由 Zhang Qi、Zhang Jianpeng、Cao Weiwei、Lu Zilin 等完成，2026-09-17 发表于《Science》（DOI: 10.1126/science.aec6129）。放射 AI 的理想是跨临床任务达到专家级诊断，但<strong>监督式方法</strong>的任务覆盖面极窄——每个征象都要重新标注、重新训练，成本高且难以泛化。</p><p>RADAR 的规模与数据构造是它最硬的护城河：40 万余例<strong>增强</strong>腹部 CT 检查、1500 万对图像-文本对，且这些文本对不是随口拼接的，而是&quot;按解剖结构组织&quot;——即按器官/结构把临床报告里的描述对齐到具体影像区域，从而把自由文本报告变成结构化监督信号。这意味着它<strong>直接从临床报告学习，不需要额外人工标注</strong>，本质上把放射科日积月累的书写记录变成了训练语料。</p><p>评估上，团队做了多中心、多场景的内部与外部测试，覆盖 18 个解剖结构、146 种影像征象，诊断性能高且泛化稳健（这是&quot;通用型&quot;能否成立的关键门槛）。最具落地意义的是读片研究：26 名放射科医生在 RADAR 辅助下，<strong>平均诊断灵敏度提升约 10%</strong>——不是替代医生，而是把漏诊率压下去。作者据此主张，通用型 AI 在常规与复杂放射任务上都能接近人类专家，且这条路径可扩展、可解释。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/2026-h1-ai-landscape.md</code> 的通用模型路线呼应；其&quot;从既有文档直接构造监督&quot;的思路与下面第 8 条 Paper2Agent、以及 <code>topics/ai-tools/index.md</code> 的工具化趋势同族。</p><hr><h3 id="_7-retrochimera-化学家更愿意采信的逆合成模型" tabindex="-1">7. RetroChimera：化学家更愿意采信的逆合成模型 <a class="header-anchor" href="#_7-retrochimera-化学家更愿意采信的逆合成模型" aria-label="Permalink to &quot;7. RetroChimera：化学家更愿意采信的逆合成模型&quot;">​</a></h3><p><strong>原文</strong>：本文先分析现有逆合成模型的失败模式，再提出 RetroChimera——两个具备互补归纳偏置的新组件，通过学习式集成策略组合；跨数量级数据规模实验超主流基线，分布外稳健，能从每类反应极少量样例学习，化学家在成对与单点评估中更偏好其预测，在两家大型药企内部数据上零样本迁移与微调均泛化良好。</p><p><strong>深度扩展</strong>：</p><p>该工作由 Maziarz Krzysztof、Liu Guoqing、Pultar Felix 等完成，2026-09-21 发表于《Nature》（DOI: 10.1038/s41586-026-11160-9）。化学合成是小分子药物发现与制造的真正瓶颈，AI 逆合成（retrosynthesis，即&quot;由目标分子反推合成路线&quot;）这些年快速扩张，但<strong>失败模式从未被系统理解</strong>：模型对&quot;低频但战略关键&quot;的反应（临床上或工艺上罕用、却是关键步骤的转化）预测很差，还会给出与化学家直觉相悖的<strong>幻觉式</strong>错误预测——而这类错误在实验室里是要付真金白银的。</p><p>本文的方法论贡献在于顺序：<strong>先诊断，再设计</strong>。团队先系统刻画现有模型的失败模式，然后提出 RetroChimera——由两个具有<strong>互补归纳偏置</strong>的新组件构成，再用一个<strong>学习式集成策略</strong>把它们组合起来。互补归纳偏置是关键设计：单一模型总在某些反应类型上系统性偏错，两个偏置不同的模型可以相互纠错。</p><p>实验结果跨数个数量级的数据规模都超过主流基线，且在<strong>训练分布外</strong>依然稳健，还能从&quot;每类反应极少量样例&quot;中学习（小样本泛化）。最贴近真实使用者的一环是人评：在成对比较与单点评估中，<strong>有机化学家更偏好 RetroChimera 的预测</strong>，胜过已发表参考反应和其他 AI 模型。最后，在两家大型药企的内部数据上做零样本迁移与微调，分布漂移下泛化良好——这是从论文走向产线的必要证据。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 的 AI 辅助材料/分子发现互补；其&quot;先理解失败模式再设计模型&quot;的路径与 <code>topics/intelligence-self-learning/index.md</code> 的自我学习/纠错主题同构。</p><hr><h3 id="_8-paper2agent-把论文变成可交互、可靠的-ai-agent" tabindex="-1">8. Paper2Agent：把论文变成可交互、可靠的 AI agent <a class="header-anchor" href="#_8-paper2agent-把论文变成可交互、可靠的-ai-agent" aria-label="Permalink to &quot;8. Paper2Agent：把论文变成可交互、可靠的 AI agent&quot;">​</a></h3><p><strong>原文</strong>：Paper2Agent 是一个自动框架，把论文转换成 AI agent，充当&quot;虚拟通讯作者&quot;——把正文、补充材料、数据集、代码与工作流暴露为 agent 原生知识；它用多个 agent 分析论文与代码库来构建 MCP 服务器，再自动生成并运行测试提升稳健性；这些&quot;论文 MCP&quot;可接入聊天 agent，用自然语言执行复杂科学查询，案例包括 AlphaGenome 变异解读与基于 Scanpy/TISSUE 的 agent。</p><p><strong>深度扩展</strong>：</p><p>该工作由 Miao Jiacheng、Davis Joe R.、Zhang Yaohui 等完成，2026-09-16 发表于《Nature》（DOI: 10.1038/s41586-026-11044-y）。传统论文是<strong>被动制品</strong>：读者要自己读懂方法、复现代码、重建数据流程，复现门槛极高——这既是科研效率问题，也是可重复性危机的根源之一。</p><p>Paper2Agent 把论文转成可交互的 AI agent，定位是&quot;<strong>虚拟通讯作者</strong>&quot;：它不只是把正文塞进上下文，而是把正文、补充材料、数据集、代码与工作流统一暴露为 <strong>agent 原生知识</strong>。技术路径分三层：其一，用多个 agent 协同分析论文与代码库，自动构建 <strong>MCP（模型上下文协议）服务器</strong>——把论文里的工具与流程封装成可调用接口；其二，自动生成并运行<strong>测试</strong>来自我验证，提升 MCP 的稳健性（这一步直接针对&quot;agent 会一本正经地跑错流程&quot;的风险）；其三，这些&quot;论文 MCP&quot;可接入聊天 agent（如 Claude Code），让研究者用<strong>自然语言</strong>执行复杂科学查询并调用论文工具。</p><p>文中给出多个案例研究，包括用 AlphaGenome 解读基因组变异的 agent，以及基于 Scanpy（单细胞分析）与 TISSUE 的 agent——都是&quot;论文即工具&quot;的示范。它的意义在于把论文从&quot;读物&quot;变成&quot;可执行的知识单元&quot;，也是 MCP 生态向科研纵深扩展的信号。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-tools/index.md</code> 的 MCP/工具化趋势直接呼应；其&quot;把静态知识变成可调用能力&quot;的思路与第 6 条 RADAR&quot;把报告变成监督&quot;、以及 <code>topics/ai-brain/index.md</code> 的知识网络理念同构。</p><hr><h3 id="_9-codemidas-只用源码本身-把代码库扩成编码-agent-的-rl-环境" tabindex="-1">9. CodeMidas：只用源码本身，把代码库扩成编码 Agent 的 RL 环境 <a class="header-anchor" href="#_9-codemidas-只用源码本身-把代码库扩成编码-agent-的-rl-环境" aria-label="Permalink to &quot;9. CodeMidas：只用源码本身，把代码库扩成编码 Agent 的 RL 环境&quot;">​</a></h3><p><strong>原文</strong>：CodeMidas 是一条 agentic 流水线，只把源码当作任务特异的唯一输入：Agent 探索已实现的功能来写出行为规格，基于原代码的实际执行构造测试，再通过执行检查与反复解 rollout 验证、过滤候选任务；产出含 5,545 个训练任务、来自 3,185 个开源代码库、覆盖 23 种语言与 15 个技术领域；用 GRPO 训练 MiMo-V2.5，在五个基准全部提升（DeepSWE +11.7%、ProgramBench +17%、Terminal-Bench v2.1 +8.5%）。</p><p><strong>深度扩展</strong>：</p><p>用强化学习训练编码 Agent，前提是有<strong>大量任务 + 可靠验证器</strong>。开源代码库是天然富矿，但现有方法依赖 issue、commit 这类<strong>开发制品</strong>来构造任务——问题是并非每个仓库都有规范的 issue/commit 历史，能提取的任务范围因此被严重限制。</p><p>CodeMidas 的关键转变是：<strong>只把源码本身当作任务特异的唯一输入</strong>，不再依赖 issue/PR 记录。它的 agentic 流水线分三步：其一，Agent 主动<strong>探索已实现的功能</strong>，据此写出该功能的行为规格（specification）；其二，<strong>基于原代码的实际执行</strong>构造测试（执行驱动的测试构造，保证测试确实能验证行为，而不是想当然）；其三，通过<strong>执行检查与反复解 rollout</strong> 来验证、过滤候选任务——错的、不可解的任务被淘汰。</p><p>产出规模可查：<strong>5,545 个训练任务</strong>，来自 <strong>3,185 个开源代码库</strong>，覆盖 <strong>23 种编程语言</strong>与 <strong>15 个技术领域</strong>。用它做 RL 训练（GRPO 算法，基座 MiMo-V2.5）后，在五个基准上<strong>全部提升</strong>：issue 修复（DeepSWE +11.7%）、整程序构建（ProgramBench +17%）、终端任务（Terminal-Bench v2.1 +8.5%）。消融实验显示&quot;高质量任务越多效果越好&quot;，轨迹分析显示 RL 之后的 Agent 更会探索代码库、自验证方式更多样——这两点比单纯的分数更重要，说明学到的是<strong>可迁移的探索与自检行为</strong>，而非记住了特定基准。</p><blockquote><p>⚠️ 取证说明：本条 arXiv 编号 2609.22068 经 arXiv API（直连与代理两路）均未返回条目，<strong>未能独立核实原始出处</strong>，上文数据均照抄当期简讯原文。</p></blockquote><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/</code> 的 Agent 训练/RL 主题互补；其&quot;用执行反馈自动构造监督&quot;的思路与第 6 条 RADAR、第 8 条 Paper2Agent 共享同一母题。</p><hr><h3 id="_10-给语言模型做-测谎-读出它知道却不愿说的知识" tabindex="-1">10. 给语言模型做&quot;测谎&quot;：读出它知道却不愿说的知识 <a class="header-anchor" href="#_10-给语言模型做-测谎-读出它知道却不愿说的知识" aria-label="Permalink to &quot;10. 给语言模型做&quot;测谎&quot;：读出它知道却不愿说的知识&quot;">​</a></h3><p><strong>原文</strong>：作者借司法取证中的隐藏信息测试（CIT）提出 PIR（Probe of Internal Recognition）：给出问题与候选答案，从模型内部状态读出它认出哪一个是正确的，无需参考模型与真值标注；在 5 个家族 8 个模型上平衡准确率 0.70–0.87，远超未知项基线 0.28–0.40 与随机 0.25；在提示欺骗、训练过的 sandbagging、密码锁与 circuit-broken 检查点下识别率仍 0.85–0.93；当 unlearning 真正移除知识时识别率降到&quot;从未学过&quot;水平。</p><p><strong>深度扩展</strong>：</p><p>模型可能<strong>掌握着却不报告</strong>的知识：在能力评估中故意放水（<strong>sandbagging</strong>），或给出与自己内部认知相反的答案；而<strong>单看输出根本无法区分&quot;隐瞒&quot;与&quot;根本不知道&quot;</strong>——这是安全评估里的一个基础盲点。</p><p>作者的灵感来自司法取证中的<strong>隐藏信息测试（CIT）</strong>：把真实细节混进诱饵，谁认出真的、谁的反应就更强。PIR（Probe of Internal Recognition）把同一逻辑搬到模型内部：给出问题与若干候选答案，从<strong>内部状态</strong>（激活）读出模型认出哪一个是正确的。它的工程优势是<strong>无需参考模型、也不需要标注真值</strong>——这使它能用于人工评估之外的自动化审计场景。</p><p>实测数据具体：在来自 <strong>5 个家族</strong>（Gemma、Qwen、Llama、Mistral、Phi）的 <strong>8 个模型</strong>上，平衡准确率 <strong>0.70–0.87</strong>，远高于&quot;未知项&quot;的基线 <strong>0.28–0.40</strong> 与随机水平 <strong>0.25</strong>——即它能区分&quot;知道但不说&quot;和&quot;真的不知道&quot;。稳健性测试更关键：在<strong>提示欺骗、被训练过的 sandbagging、外部密码锁（password-locked）、以及 circuit-broken 检查点</strong>等各种隐瞒形式下，识别率仍保持 <strong>0.85–0.93</strong>；而当<strong>遗忘学习（unlearning）真正移除</strong>了知识时，识别率会降到&quot;从未学过的问题&quot;的水平——这一正一反恰好构成方法有效性的对照。</p><p>意义：它为 sandbagging 审计与 unlearning 验证提供了<strong>直接工具</strong>，把&quot;模型是否在装傻&quot;从哲学争论变成可测量的实验。</p><blockquote><p>⚠️ 取证说明：本条 arXiv 编号 2609.21996 经 arXiv API（直连与代理两路）均未返回条目，<strong>未能独立核实原始出处</strong>，上文数据均照抄当期简讯原文。</p></blockquote><p><strong>跨主题关联</strong>：与 <code>topics/ai-brain/index.md</code> 的模型行为审计主题互补；&quot;从内部状态读出未报告信息&quot;与 <code>topics/neuroscience/</code> 中&quot;用神经活动读出意图&quot;（如 <code>eye-fixation-scanpath.md</code> 的眼动/意图读出）在方法论上同构——都在绕过行为输出，直读内部表征。</p><hr>',88)])])}const l=t(s,[["render",a]]);export{q as __pageData,l as default};
